async function main() {
  console.log('🌸 Seeding all CCTV cameras...')
  await prisma.camera.deleteMany({
    where: { wilayah: { not: 'POLDA METRO JAYA' } }
  })
  console.log('🗑️ Cleaned old data')

  const batchSize = 100
  let total = 0
  for (let i = 0; i < allCameras.length; i += batchSize) {
    const batch = allCameras.slice(i, i + batchSize)
    await prisma.camera.createMany({ data: batch, skipDuplicates: true })
    total += batch.length
    console.log('✅ Inserted ' + total + '/' + allCameras.length)
  }
  console.log('🎉 Done! Total cameras: ' + allCameras.length)
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())